 "content": "def transform(grid):
    g = [row[:] for row in grid]
    # The full-width color-2 row is the divider. Project the shared
    # occupied columns of the two color-matched boundary patterns upward
    # from the upper boundary to the divider in color 4.
    divider = next(r for r, row in enumerate(g) if all(v == 2 for v in row))
    top_color = next(v for v in g[0] if v != 0)
    top_cols = {c for c, v in enumerate(g[0]) if v == top_color}
    bottom_row = next(row for row in reversed(g[divider + 1:]) if any(row))
    bottom_cols = {c for c, v in enumerate(bottom_row) if v == top_color}
    for c in top_cols & bottom_cols:
        for r in range(1, divider):
            if g[r][c] == 0:
                g[r][c] = 4
    return g
